def main():
    T = int(input())
    results = []
    for _ in range(T):
        N = int(input())
        A = list(map(int, input().split()))
        P = list(map(int, input().split()))
        Q = int(input())
        operations = [list(map(int, input().split())) for _ in range(Q)]

        # Apply operations
        for op in operations:
            if op[0] == 1:
                A = [A[P[i] - 1] for i in range(N)]
            elif op[0] == 2:
                x, y = op[1] - 1, op[2] - 1
                A[x], A[y] = A[y], A[x]
            elif op[0] == 3:
                x = op[1] - 1
                results.append(A[x])

    # Output results
    for result in results:
        print(result)

main()
